changeSet.sql:
INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'resilience.circuitbreaker.api2.failure-rate-threshold', '50', 'NUMBER', 'Порог частоты ошибок (%) для размыкания circuit breaker — api2.', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'resilience.circuitbreaker.api2.failure-rate-threshold');

